/**
 * Mehrwertsteuer Rechner - PDF-Schriftart (Roboto Subset)
 * Unterstuetzt: Deutsch, Englisch, Franzoesisch, Tuerkisch + Euro-Zeichen
 * Quelle: Roboto (Apache License 2.0, Google) - auf benoetigte Zeichen reduziert
 * Version 1.2.7
 */
(function() {
    'use strict';
    var fontData = '';

    // Registriert die Schrift in einem jsPDF-Dokument
    window.mwstRegisterPdfFont = function(doc) {
        try {
            doc.addFileToVFS('Roboto-Regular.ttf', fontData);
            doc.addFont('Roboto-Regular.ttf', 'Roboto', 'normal');
            doc.setFont('Roboto', 'normal');
            return true;
        } catch (e) {
            return false;
        }
    };
})();